import {initEmotionCraft} from './emotion-craft.mjs';
import {initEmotionJourney} from './emotion-journey.mjs';
const $=id=>document.getElementById(id);
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const clock=s=>`${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;
const goalLabels={audience:'写给谁',message:'这首歌想说什么',feeling:'听完希望留下什么感觉',style:'希望有什么音乐气质',scenes:'故事、人物与时代细节',keep:'重要的保留项',avoid:'想避免什么',acceptance:'怎样才算达到了目标'};
const trackLabels={piano:'钢琴',guitar:'吉他',bass:'贝斯',drums:'鼓',strings:'弦乐',vocal:'人声'};
async function api(path='',data){const response=await fetch('/api/song-project'+path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const value=await response.json();if(!response.ok)throw Error(value.error||'暂时无法完成，请重试。');return value;}
export async function initSongProject({score,audition,setVersion,getPlayback,pauseMain}){
  const host=$('song-project');if(!host)return;
  let snapshot,brief,dirty=false,busy=false,selected='original',timer,requestId,editCounter=0,activeJob,draftRevision,journey,craft,pendingScope;
  const banner=el('div',undefined,'section-head');const heading=el('div');heading.append(el('span','THE FEELING BEHIND THE SONG','eyebrow'),el('h2','让整首歌，走到你想要的情绪。'));const saveDirection=el('button','保存创作目标');saveDirection.id='save-direction';saveDirection.disabled=true;saveDirection.onclick=prepare;banner.append(heading,saveDirection);host.append(banner);
  const tabs=el('div',undefined,'project-tabs');const panels={};
  for(const [id,label] of [['sections','情绪与段落'],['goal','作品目标'],['craft','乐句与演唱'],['produce','混音与版本']]){const b=el('button',label);b.type='button';b.id=`project-tab-${id}`;b.setAttribute('aria-controls',`project-panel-${id}`);b.setAttribute('aria-pressed',String(id==='sections'));b.onclick=()=>show(id);tabs.append(b);const panel=el('section');panel.id=`project-panel-${id}`;panel.setAttribute('aria-labelledby',b.id);panel.hidden=id!=='sections';panels[id]=panel;}host.append(tabs,...Object.values(panels));
  const feedback=el('p','正在读取创作依据…','project-status');feedback.id='project-status';feedback.setAttribute('role','status');tabs.before(feedback);
  function message(value,error=false){feedback.textContent=value;feedback.classList.toggle('error',error);}
  function show(id){for(const [key,p] of Object.entries(panels)){p.hidden=key!==id;$(`project-tab-${key}`).setAttribute('aria-pressed',String(key===id));}}
  function markDirty(){dirty=true;editCounter++;requestId=null;saveDirection.textContent='保存修改后的目标';saveDirection.classList.add('primary');journey?.sync();if($('render-project'))$('render-project').disabled=true;if($('project-proposal'))$('project-proposal').hidden=true;message('目标有未保存的修改。保存后带入下一次创作，已有音频保持原样。');}
  window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
  function field(parent,label,value,onInput,id,rows=2,max=600){const wrap=el('label',label,'project-field');const control=el('textarea');control.id=id;control.value=value;control.rows=rows;control.maxLength=max;control.addEventListener('input',()=>{onInput(control.value);markDirty();});wrap.append(control);parent.append(wrap);return control;}
  function drawGoals(){panels.goal.replaceChildren();panels.goal.append(el('h3','这首歌，要把什么留给听众？'),el('p','先确定故事与感受，再让词、曲、唱共同服务于它。音乐类型决定表达方式，不替代情绪目标。','project-intro'));
    const grid=el('div',undefined,'goal-grid');for(const key of ['message','feeling','audience','style'])field(grid,goalLabels[key],brief.goal[key],value=>brief.goal[key]=value,`goal-${key}`);panels.goal.append(grid);
    const details=el('details');details.append(el('summary','故事细节、保留内容与验收标准'));const more=el('div',undefined,'goal-grid');for(const key of ['scenes','keep','avoid','acceptance'])field(more,goalLabels[key],brief.goal[key],value=>brief.goal[key]=value,`goal-${key}`);details.append(more);panels.goal.append(details);
    const next=el('button','把目标安排到各段落 →');next.onclick=()=>show('sections');panels.goal.append(next);
  }
  function drawSections(){panels.sections.replaceChildren();journey=initEmotionJourney(panels.sections,{state:journey?.state,score,getBrief:()=>brief,getRecords:()=>snapshot.observations||[],getPlayback,isDirty:()=>dirty,onChange:markDirty,onListen:audition,onCraft:id=>{show('craft');pendingScope=id;craft?.selectScope(id);},onObserve:async input=>{const record=await api('/observations',{...input,revision:draftRevision});snapshot.observations||=[];if(!snapshot.observations.some(r=>r.id===record.id))snapshot.observations.push(record);}});
  }
  function drawProduce(){panels.produce.replaceChildren();panels.produce.append(el('p','每次从原始分轨制作一个新版本。先核对影响范围，再确认试听。目标文字的变化不会自动改写已有歌词、乐谱或演唱。','project-intro'));
    const settings=el('details');settings.append(el('summary','选择各段的音轨层次调整'));const grid=el('div',undefined,'goal-grid');for(const s of score.sections){const p=brief.sections.find(p=>p.id===s.id),wrap=el('label',s.name,'project-field'),choice=el('select');for(const [key,value] of Object.entries(snapshot.recipes)){const option=el('option',value.name);option.value=key;choice.append(option);}choice.value=p.treatment;choice.onchange=()=>{p.treatment=choice.value;markDirty();};wrap.append(choice);grid.append(wrap);}settings.append(grid);panels.produce.append(settings);
    const save=el('button','保存创作依据，查看制作方案','primary');save.id='prepare-project';save.disabled=busy;save.onclick=prepare;panels.produce.append(save);
    const proposal=el('div',undefined,'proposal');proposal.id='project-proposal';proposal.hidden=dirty||!snapshot.draft.proposal;panels.produce.append(proposal);
    if(snapshot.draft.proposal){const plan=snapshot.draft.proposal.plan;proposal.append(el('h3','本轮会执行什么'));if(!plan.changes.length)proposal.append(el('p','创作依据已保存。各段落当前都选择保留声音；如需新试听，请到“段落协同”选择声音调整。'));
      for(const c of plan.changes){const card=el('div',undefined,'change-row');card.append(el('b',`${c.name} · ${clock(c.start)}–${clock(c.end)}`),el('p',`${c.emotion} → ${c.treatmentName}`));const details=el('details');details.append(el('summary','查看具体参数与范围'));details.append(el('p',Object.entries(c.gains).map(([k,v])=>`${trackLabels[k]} ${v>0?'+':''}${v} dB`).join(' · ')),el('p',`人声空间量 ${c.room}（原版 0.26）；段落两端各 120 毫秒渐变，范围外音频保留。`));card.append(details);proposal.append(card);}
      const pending=el('div',undefined,'pending');pending.append(el('b','仍然需要创作与试听解决'));for(const item of plan.pending)pending.append(el('p',item));proposal.append(pending);
      const render=el('button','确认方案，制作新试听','primary');render.id='render-project';render.disabled=busy||dirty||!plan.changes.length||!snapshot.available||snapshot.versions.some(v=>v.state==='rendering');
      render.onclick=produce;proposal.append(render);
    }
    drawVersions();
  }
  function drawVersions(){let area=$('project-versions');if(area)area.remove();area=el('div',undefined,'project-versions');area.id='project-versions';area.append(el('h3','版本与试听判断'));
    const success=snapshot.versions.filter(v=>v.state==='succeeded'),label=el('label','选择版本','project-field'),selector=el('select');selector.id='project-version';const original=el('option','V1 · 原始演唱小样');original.value='original';selector.append(original);for(const v of success){const o=el('option',`V${v.number} · ${v.proposal.plan.changes.length} 处声音调整${v.review?' · 已记听感':' · 待试听'}`);o.value=v.id;selector.append(o);}selector.value=selected;if(!selector.value){selected='original';selector.value=selected;}selector.onchange=()=>{selected=selector.value;drawVersions();};label.append(selector);area.append(label);
    for(const v of snapshot.versions.filter(v=>v.state!=='succeeded')){const row=el('div',undefined,'version-status');row.append(el('p',`V${v.number} · ${v.message}`));if(v.state==='rendering'){const cancel=el('button','取消这次制作');cancel.onclick=async()=>{try{await api(`/${v.id}/cancel`,{});await refresh();message('制作已取消，原版保留。');}catch(e){message(e.message,true);}};row.append(cancel);}area.append(row);}
    const version=snapshot.versions.find(v=>v.id===selected),actions=el('div',undefined,'project-actions');const a=el('button','切到原版 A');a.onclick=()=>{setVersion(null,'V1 原版');message('已切到原版，保留当前播放位置。上方播放器可继续试听。');};actions.append(a);
    if(version){const b=el('button',`切到这一版 B · V${version.number}`,'primary');b.id='compare-project';b.onclick=()=>{setVersion(version.id,`V${version.number}`);message('已切到这版，保留当前播放位置。请听相同段落再判断。');};actions.append(b);area.append(el('p',`这版的目标：${version.proposal.brief.goal.message}`,'version-goal'));}
    area.append(actions,el('p','A/B 使用无损音频并保持播放位置，可在上方播放器继续听。各版音量可能有差别，请结合层次和表达判断。','project-intro'));
    if(version){const links=el('div',undefined,'downloads');for(const [kind,text] of [['song','演唱 WAV ↓'],['accompaniment','伴奏 WAV ↓'],['record','创作记录 JSON ↓']]){const link=el('a',text);link.href=`/api/song-project/${version.id}/assets/${kind}`;link.download=`那条放学后的路-V${version.number}-${kind}.${kind==='record'?'json':'wav'}`;links.append(link);}area.append(links,el('p','创作记录含目标、段落方案、乐谱、制作参数和素材索引；不包含音频文件。','honest'));
      const review=el('form',undefined,'review-form');review.append(el('h4','这版是否更接近想表达的感觉？'));const verdict=el('select');verdict.id='project-verdict';verdict.setAttribute('aria-label','试听结论');for(const [value,text] of [['','请选择你的听感'],['closer','更接近了'],['unsure','还不能确定'],['worse','更远了']]){const o=el('option',text);o.value=value;verdict.append(o);}verdict.required=true;verdict.value=version.review?.verdict||'';const note=el('textarea');note.id='project-review';note.setAttribute('aria-label','具体听感');note.placeholder='例如：副歌的鼓更清楚了，但最后一句还不够放松。';note.value=version.review?.note||'';note.rows=3;note.maxLength=1200;note.minLength=2;note.required=true;const submit=el('button','保存我的试听意见');submit.type='submit';review.append(verdict,note,submit);review.onsubmit=async event=>{event.preventDefault();const playback=getPlayback();if(playback.version!==version.id||playback.mode!=='song'||playback.listenedSeconds<2){message('请先切到这一版 B 并试听，再保存对这一版的意见。',true);return;}submit.disabled=true;try{await api(`/${version.id}/review`,{verdict:verdict.value,note:note.value});await refresh();message('已保存你的听感，后续修改可以从这些问题继续。');}catch(e){submit.disabled=false;message(e.message,true);}};area.append(review);
    }else area.append(el('p','原版歌词、乐谱与音频可在上方试听区下载。','project-intro'));
    panels.produce.append(area);
  }
  async function prepare(){if(busy)return false;busy=true;saveDirection.disabled=true;$('prepare-project').disabled=true;const counter=editCounter;message('正在保存创作依据并核对原始素材…');try{snapshot=await api('/prepare',{revision:draftRevision,brief:structuredClone(brief)});draftRevision=snapshot.draft.revision;if(counter===editCounter){dirty=false;brief=structuredClone(snapshot.draft.brief);drawGoals();drawSections();saveDirection.textContent='创作目标已保存';saveDirection.classList.remove('primary');}requestId=null;drawProduce();message(dirty?'保存期间又有编辑，请再次保存。':`目标已保存 · 第 ${draftRevision} 次保存。下一份乐句草稿会使用这些情绪要求。`);return !dirty;}catch(e){message(e.message,true);return false;}finally{busy=false;saveDirection.disabled=false;$('prepare-project').disabled=false;if($('render-project'))$('render-project').disabled=dirty||!snapshot.draft.proposal?.plan.changes.length||!snapshot.available||snapshot.versions.some(v=>v.state==='rendering');}}
  async function produce(){if(dirty||busy)return;busy=true;$('render-project').disabled=true;message('正在提交已确认的制作方案…');try{requestId||=crypto.randomUUID();const job=await api('/render',{hash:snapshot.draft.proposal.hash,requestId});activeJob=job.id;await refresh();message(job.message);}catch(e){message(e.message,true);}finally{busy=false;drawProduce();}}
  async function refresh(){const fresh=await api();snapshot={...fresh,draft:snapshot.draft};const done=snapshot.versions.find(v=>v.id===activeJob&&v.state!=='rendering');if(done){if(done.state==='succeeded')selected=done.id;message(done.message,done.state==='failed');activeJob=null;}drawProduce();clearTimeout(timer);if(snapshot.versions.some(v=>v.state==='rendering'))timer=setTimeout(()=>refresh().catch(e=>{message(e.message,true);timer=setTimeout(()=>refresh().catch(()=>{}),3000);}),1500);}
  try{snapshot=await api();draftRevision=snapshot.draft.revision;activeJob=snapshot.versions.find(v=>v.state==='rendering')?.id;brief=structuredClone(snapshot.draft.brief);drawGoals();drawSections();drawProduce();saveDirection.disabled=false;message(snapshot.draft.revision?`已载入创作目标 · 第 ${snapshot.draft.revision} 次保存。起伏曲线是目标建议，可按听感调整。`:'样本的创作目标已预填，可按你的理解修改。');if(snapshot.versions.some(v=>v.state==='rendering'))await refresh();craft=await initEmotionCraft(panels.craft,{score,context:()=>({dirty,revision:draftRevision}),saveContext:prepare,setVersion,getPlayback,pauseMain,audition});if(pendingScope)craft.selectScope(pendingScope);}catch(e){message('创作依据暂不可用：'+e.message,true);}
  return {updatePlayback:()=>journey?.updatePlayback()};
}


